import{_ as e,o as r,c as a,a2 as o}from"./chunks/framework.Cm6XCzck.js";const g=JSON.parse('{"title":"研究情报系统 V1.0","description":"","frontmatter":{"title":"研究情报系统 V1.0","outline":"deep"},"headers":[],"relativePath":"zh/runtime/research-intelligence.md","filePath":"zh/runtime/research-intelligence.md","lastUpdated":1786174449000}'),n={name:"zh/runtime/research-intelligence.md"};function d(i,t,l,s,h,c){return r(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="研究情报系统-v1-0" tabindex="-1">研究情报系统 V1.0 <a class="header-anchor" href="#研究情报系统-v1-0" aria-label="Permalink to &quot;研究情报系统 V1.0&quot;">​</a></h1><h2 id="一句话定义" tabindex="-1">一句话定义 <a class="header-anchor" href="#一句话定义" aria-label="Permalink to &quot;一句话定义&quot;">​</a></h2><p>研究情报系统把“从哪里找”和“研究什么”分开：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>三条情报来源管线</span></span>
<span class="line"><span>↓</span></span>
<span class="line"><span>统一信号池与去重</span></span>
<span class="line"><span>↓</span></span>
<span class="line"><span>三个长期研究栏目</span></span></code></pre></div><h2 id="情报源地图-intelligence-sources" tabindex="-1">情报源地图 / Intelligence Sources <a class="header-anchor" href="#情报源地图-intelligence-sources" aria-label="Permalink to &quot;情报源地图 / Intelligence Sources&quot;">​</a></h2><p>这里用简单中英文说明数字研究员正式监控的主要来源。完整、机器可执行的 Watchlist 以 <a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/intelligence/REGISTRY.json" target="_blank" rel="noreferrer"><code>research/intelligence/REGISTRY.json</code></a> 为唯一事实源。</p><h3 id="ai-平台-ai-platforms" tabindex="-1">AI 平台 / AI Platforms <a class="header-anchor" href="#ai-平台-ai-platforms" aria-label="Permalink to &quot;AI 平台 / AI Platforms&quot;">​</a></h3><table tabindex="0"><thead><tr><th>来源</th><th>简单说明</th><th>频率</th><th>主要关注</th></tr></thead><tbody><tr><td>OpenAI</td><td>OpenAI 官方产品、开发者文档与研究入口</td><td>P0 · 每日</td><td>ChatGPT、Codex、API、Agents、企业控制</td></tr><tr><td>Anthropic / Claude</td><td>Anthropic 与 Claude 官方信息</td><td>P0 · 每日</td><td>Claude、Claude Code、API、Agent 治理</td></tr><tr><td>Google / Gemini</td><td>Google Gemini 官方开发与产品信息</td><td>P0 · 每日</td><td>Gemini API、AI Studio、Vertex AI、Gemini CLI、ADK</td></tr><tr><td>Cursor</td><td>Cursor 官方开发工具与 Agent 平台</td><td>P0 · 每日</td><td>Coding Agent、Cloud Agent、CLI、工程工作流</td></tr><tr><td>GitHub Copilot</td><td>GitHub 官方 AI 编程产品</td><td>P0 · 每日</td><td>Copilot、Coding Agent、CLI、Code Review</td></tr><tr><td>Microsoft Copilot Platform</td><td>微软 Copilot 与企业 Agent 平台</td><td>P0 · 每日</td><td>Microsoft 365 Copilot、Copilot Studio、Agent Builder、Power Platform</td></tr></tbody></table><p>每个平台不仅看首页，还按 Registry 检查 Release Notes、官方文档、社区/论坛、官方 GitHub、Roadmap 或 Status 等正式入口。</p><h3 id="github-工程仓库-engineering-repositories" tabindex="-1">GitHub 工程仓库 / Engineering Repositories <a class="header-anchor" href="#github-工程仓库-engineering-repositories" aria-label="Permalink to &quot;GitHub 工程仓库 / Engineering Repositories&quot;">​</a></h3><p><strong>P0 · 每日</strong></p><table tabindex="0"><thead><tr><th>仓库</th><th>简单说明</th><th>主要关注</th></tr></thead><tbody><tr><td><a href="https://github.com/openai/codex" target="_blank" rel="noreferrer">openai/codex</a></td><td>OpenAI Codex 开源工程仓库</td><td>Coding Agent、Runtime、Sandbox、权限、Review、Protocol</td></tr><tr><td><a href="https://github.com/openai/openai-agents-python" target="_blank" rel="noreferrer">openai/openai-agents-python</a></td><td>OpenAI Agents Python SDK</td><td>Agent SDK、工具、Handoff、Tracing、运行机制</td></tr><tr><td><a href="https://github.com/anthropics/claude-code" target="_blank" rel="noreferrer">anthropics/claude-code</a></td><td>Anthropic Claude Code 工程仓库</td><td>Coding Agent、工具调用、权限、Session、恢复</td></tr><tr><td><a href="https://github.com/google-gemini/gemini-cli" target="_blank" rel="noreferrer">google-gemini/gemini-cli</a></td><td>Google Gemini CLI</td><td>CLI Agent、工具、执行环境、交互协议</td></tr><tr><td><a href="https://github.com/google/adk-python" target="_blank" rel="noreferrer">google/adk-python</a></td><td>Google Agent Development Kit Python</td><td>Agent 开发框架、Workflow、工具与运行时</td></tr><tr><td><a href="https://github.com/github/copilot-cli" target="_blank" rel="noreferrer">github/copilot-cli</a></td><td>GitHub Copilot CLI</td><td>终端 Agent、Coding Workflow、执行与权限</td></tr><tr><td><a href="https://github.com/modelcontextprotocol/python-sdk" target="_blank" rel="noreferrer">modelcontextprotocol/python-sdk</a></td><td>MCP Python SDK</td><td>Model Context Protocol Python 实现</td></tr><tr><td><a href="https://github.com/modelcontextprotocol/typescript-sdk" target="_blank" rel="noreferrer">modelcontextprotocol/typescript-sdk</a></td><td>MCP TypeScript SDK</td><td>Model Context Protocol TypeScript 实现</td></tr><tr><td><a href="https://github.com/a2aproject/A2A" target="_blank" rel="noreferrer">a2aproject/A2A</a></td><td>Agent2Agent 协议项目</td><td>Agent 间协议、互操作、任务与消息边界</td></tr></tbody></table><p>Registry 还维护 P1 周度仓库，包括 AutoGen、Semantic Kernel、LangGraph、CrewAI、OpenHands、browser-use、SWE-bench、SWE-agent、Langfuse 和 Phoenix 等。</p><h3 id="论文与研究成果-published-research" tabindex="-1">论文与研究成果 / Published Research <a class="header-anchor" href="#论文与研究成果-published-research" aria-label="Permalink to &quot;论文与研究成果 / Published Research&quot;">​</a></h3><p><strong>P0 · 每日</strong></p><table tabindex="0"><thead><tr><th>来源</th><th>中文解释</th><th>主要关注</th></tr></thead><tbody><tr><td><a href="https://arxiv.org/" target="_blank" rel="noreferrer">arXiv</a></td><td>开放学术预印本平台</td><td><code>cs.MA</code> 多智能体、<code>cs.SE</code> 软件工程、<code>cs.AI</code> 人工智能</td></tr><tr><td><a href="https://link.springer.com/journal/10458" target="_blank" rel="noreferrer">Autonomous Agents and Multi-Agent Systems</a></td><td>《自主智能体与多智能体系统》期刊（JAAMAS）</td><td>Multi-Agent、Agent 组织、协调、协议、治理</td></tr><tr><td><a href="https://www.sciencedirect.com/journal/journal-of-systems-and-software" target="_blank" rel="noreferrer">Journal of Systems and Software</a></td><td>《系统与软件》期刊（JSS）</td><td>软件架构、软件工程、实证评估、可复现工程</td></tr><tr><td><a href="https://zenodo.org/" target="_blank" rel="noreferrer">Zenodo</a></td><td>开放科研成果与 DOI 存档平台</td><td>论文附件、软件、数据集、Artifact、复现证据</td></tr><tr><td><a href="https://openreview.net/" target="_blank" rel="noreferrer">OpenReview</a></td><td>开放同行评审平台</td><td>论文、公开评审、会议研究成果</td></tr><tr><td><a href="https://openai.com/research/" target="_blank" rel="noreferrer">OpenAI Research</a></td><td>OpenAI 官方研究</td><td>Agent、模型、系统、安全与技术报告</td></tr><tr><td><a href="https://www.anthropic.com/research" target="_blank" rel="noreferrer">Anthropic Research</a></td><td>Anthropic 官方研究</td><td>Agent、安全、模型行为与治理</td></tr><tr><td><a href="https://deepmind.google/research/" target="_blank" rel="noreferrer">Google DeepMind Research</a></td><td>Google DeepMind 官方研究</td><td>Agent、AI 系统、模型与前沿研究</td></tr><tr><td><a href="https://www.microsoft.com/en-us/research/" target="_blank" rel="noreferrer">Microsoft Research</a></td><td><strong>微软研究院 / Microsoft 官方研究机构</strong></td><td>Agent 系统、企业 AI、软件工程、系统架构与 Benchmark</td></tr></tbody></table><p><strong>P1 · 每周</strong>还包括 ACL Anthology、PMLR、NeurIPS Proceedings、ACM Digital Library 和 IEEE Xplore。</p><blockquote><p>原则：Daily Discovery 的正式来源优先使用公开、无需私人登录态的入口。若全文受限，记录访问状态，不把“无法读取全文”等同于“没有研究对象”。</p></blockquote><h2 id="三条情报发现-skill" tabindex="-1">三条情报发现 Skill <a class="header-anchor" href="#三条情报发现-skill" aria-label="Permalink to &quot;三条情报发现 Skill&quot;">​</a></h2><h3 id="ai-平台变更情报发现" tabindex="-1">AI 平台变更情报发现 <a class="header-anchor" href="#ai-平台变更情报发现" aria-label="Permalink to &quot;AI 平台变更情报发现&quot;">​</a></h3><p>每日观察主要 AI 平台的官方更新，包括 Release Notes、文档、论坛或社区、API 变化、企业控制、状态页和官方 GitHub。</p><h3 id="github-工程情报发现" tabindex="-1">GitHub 工程情报发现 <a class="header-anchor" href="#github-工程情报发现" aria-label="Permalink to &quot;GitHub 工程情报发现&quot;">​</a></h3><p>不扫描整个 GitHub，而是运行受控工程雷达：</p><ul><li>固定组织和仓库观察名单；</li><li>Release、Tag、已合并 PR、高价值 Issue、Discussion 与安全公告；</li><li>只扫描上次检查点之后的增量；</li><li>固定主题 × 变化类型查询；</li><li>少量新项目探索。</li></ul><h3 id="论文与研究成果情报发现" tabindex="-1">论文与研究成果情报发现 <a class="header-anchor" href="#论文与研究成果情报发现" aria-label="Permalink to &quot;论文与研究成果情报发现&quot;">​</a></h3><p>观察论文、预印本、技术报告、Benchmark、数据集、System Card / Model Card、标准规范，以及论文关联的代码、附录与评估工具。</p><h2 id="三个研究栏目" tabindex="-1">三个研究栏目 <a class="header-anchor" href="#三个研究栏目" aria-label="Permalink to &quot;三个研究栏目&quot;">​</a></h2><p>三条情报管线共同服务：</p><ol><li>数字员工；</li><li>行业架构；</li><li>开源工程。</li></ol><p>同一变化只能有一个主栏目，可以记录对另外两个栏目的次级影响。</p><h2 id="每日完成标准" tabindex="-1">每日完成标准 <a class="header-anchor" href="#每日完成标准" aria-label="Permalink to &quot;每日完成标准&quot;">​</a></h2><p>10:00 队列任务必须汇报来源覆盖、无法访问和失败来源、信号/候选/入选/拒绝数量，以及三个栏目分别“已选题”或“未选题”的明确决定。</p><p>“已检查但无重要变化”和“没有检查”不能混为一谈。</p><h2 id="权威文件" tabindex="-1">权威文件 <a class="header-anchor" href="#权威文件" aria-label="Permalink to &quot;权威文件&quot;">​</a></h2><ul><li>Registry：<a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/intelligence/REGISTRY.json" target="_blank" rel="noreferrer"><code>research/intelligence/REGISTRY.json</code></a></li><li>Daily Run：<code>research/intelligence/runs/YYYY/MM/YYYY-MM-DD-intelligence.json</code></li><li>Skill Profiles：<code>research/skills/profiles/</code></li></ul>`,35)])])}const u=e(n,[["render",d]]);export{g as __pageData,u as default};
